def triangle_type(a: float, b: float, c: float) -> str:
    """Return "equilateral", "isosceles", "scalene" or "invalid"."""
    # Check if any side is 0 or negative
    if a <= 0 or b <= 0 or c <= 0:
        return "invalid"
    # Check if any side is equal to or longer than the other two added together
    if a >= b + c or b >= a + c or c >= a + b:
        return "invalid"
    # Check if all sides are equal
    if a == b == c:
        return "equilateral"
    # Check if exactly two sides are equal
    elif a == b or b == c or a == c:
        return "isosceles"
    # If none of the above conditions are met
    return "scalene"

def triangle_type(a: float, b: float, c: float) -> str:
    """Return "equilateral", "isosceles", "scalene" or "invalid"."""
    # Check for invalid sides
    if any(side <= 0 for side in [a, b, c]) or a + b <= c or a + c <= b or b + c <= a:
        return "invalid"

    # Check for equilateral triangle
    if a == b == c:
        return "equilateral"

    # Check for isosceles triangle
    if a == b or b == c or a == c:
        return "isosceles"

    # If none of the above conditions are met, it's a scalene triangle
    return "scalene"

