    while a and b:
        if a[0] <= b[0]:
            sorted_list.append(a.pop(0))
        else:
            sorted_list.append(b.pop(0))

    # If there are remaining elements in either list, append them to the sorted list
    sorted_list.extend(a)
    sorted_list.extend(b)

