def valid_parentheses(s: str) -> bool:
    # Dictionary to map opening brackets to their corresponding closing brackets
    bracket_map = {'(': ')', '[': ']', '{': '}'}

    # Stack to keep track of opening brackets
    stack = []

    # Iterate through each character in the string
    for char in s:
        # If the character is an opening bracket, push it onto the stack
        if char in bracket_map:
            stack.append(char)
        # If the character is a closing bracket
        elif char in bracket_map.values():
            # If the stack is empty or the top of the stack does not match the corresponding opening bracket, return False
            if not stack or bracket_map[stack.pop()] != char:
                return False

    # If the stack is empty, all opening brackets have been properly closed; otherwise, return False
    return len(stack) == 0

